// Based on https://www.shadertoy.com/view/lXKBzV

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2. * fragCoord-iResolution.xy) / iResolution.y;
    vec3 color = vec3(0);
    const float SPEED = 2.0;
    vec2 ar = vec2(atan(uv.x, uv.y), length(uv));
    vec3 c1 = cos(SPEED * iTime * 0.5 + 0.1/ar.y - ar.x*vec3(1,0,-1));
    color += exp(-5. * (.5+.5*c1) * exp(-0.2/ar.y));
    color *= 1.0-1.5*dot(uv, uv)*dot(uv, uv);
    fragColor = vec4(pow(color, vec3(1.0)), 1);
}
